import json,re,collections,sys
from edshield.rules import propagate_names
from edshield.types import Entity
def rd(p): return [json.loads(l) for l in open(p)]
sets={'deterministic__comta':'experiments/genre_shift/data/planted/comta.jsonl','deterministic__mathdial':'experiments/genre_shift/data/planted/mathdial.jsonl',
'llm__comta':'data/planted_llm/comta.jsonl','llm__mathdial':'data/planted_llm/mathdial.jsonl',
'control__comta':'experiments/genre_shift/data/control/comta.jsonl','control__mathdial':'experiments/genre_shift/data/control/mathdial.jsonl'}
for s,p in sets.items():
    docs={d['doc_id']:d for d in rd(p)}
    new=0; gold_ini=0; gold_hit=0; ctx=collections.Counter()
    for r in rd(f'results/candidate/round_0/raw/{s}.jsonl'):
        d=docs[r['doc_id']]; t=d['text']
        ents=[Entity(**e) for e in r['entities']]
        out=propagate_names(t,ents)
        added=[e for e in out[len(ents):] if re.fullmatch(r'[A-Z]\.',e.text)]
        new+=len(added)
        gs={(g[0],g[1]) for g in d['gold_spans'] if re.fullmatch(r'[A-Z]\.',t[g[0]:g[1]])}
        gold_ini+=len(gs); gold_hit+=sum((e.start,e.end) in gs for e in added)
        if s.startswith('control') or 1:
            for e in added:
                if (e.start,e.end) not in gs:
                    w=t[max(0,e.start-15):e.start].split(); ctx[w[-1] if w else '']+=1
    print(s,'new',new,'gold initials',gold_ini,'hit',gold_hit,'non-gold prev words',dict(ctx))
EOF
python /tmp/preview.py

